create temp table _kbv11(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kbv11 values (53, $kbv11$[{"t":"list","id":"a1-1-4-1-v1","imp":"core","items":["1、常用输入设备概述","（1）键盘：向计算机输入字母、数字、符号、命令等信息，是计算机必不可少的输入设备。","（2）鼠标：控制屏幕上的鼠标箭头定位，通过按键发出命令；不是必备输入设备，是常用输入设备。","（3）笔输入设备：主要有手写板、手写笔，可替代键盘、鼠标输入字符、命令和作图。","（4）扫描仪：将原稿（图片、照片、底片、书稿）输入计算机的输入设备。","（5）数字摄像头：将现实世界中景物的连续图像数字化后输入计算机的视频输入设备。","（6）外部设备包括输入设备和输出设备；扫描仪、键盘、鼠标、手写板都属于输入设备。","^^2、笔输入设备（手写板）^^","^^(1) 作用：兼容键盘、鼠标和写字笔的功能（可替代键盘、鼠标输入字符、命令和作图），输入汉字需要运行“手写汉字识别软件”。^^","^^(2) 手写板分类：电阻式、电容式、电磁感应式^^","(3) 电磁感应笔：发出电磁波，基板接收后计算出笔的位置信息并传给主机，屏幕上实时显示笔迹；笔尖相当于鼠标左键、按钮 1 相当于右键、按钮 2 相当于滚轮。","^^(4) 与主机接口：串行口、USB。^^","(5) 触摸屏（智能手机、ATM 机等使用）是在液晶面板上覆盖一层压力板，对压力敏感，手指或笔尖施压时产生电流以确定位置并跟踪，再由软件识别输入信息。","==3、扫描仪（图像输入设备）==","==(1) 扫描仪是将原稿（图片、照片、底片、书稿）输入计算机的一种输入设备==","==(2) 扫描仪输入到计算机中的是原稿的“图像”（bitmap，格式为 TIF），不是图形==","==(3) 工作原理（平板式）：进行光电转换（CCD，电荷耦合器件），产生电流并输出==","==(4) 常见扫描仪类型：平板式扫描仪、滚筒式和胶片专用、手持式扫描仪。==","==①、平板式扫描仪：主要扫描反射式稿件，适用范围较广，扫描速度、精度、质量较好，适用于家庭与办公；分辨率 300~8000dpi，色彩 24 至 48 位真彩色，成像器件是 CCD（电荷耦合器件）。==","==②、滚筒式和胶片专用扫描仪：胶片专用（即底片式或接触式）分辨率高、技术性能强，多用于专业印刷排版，价格较贵，扫描透明胶片分辨率最低 1000dpi，一般 2700dpi 以上；滚筒式光学分辨率 300dpi，有彩色和灰度两种，彩色型号一般为 24 位，极少数采用 CCD 技术。==","==③、手持式扫描仪：扫描头较窄，只适用于扫描较小的图件。==","==(5) 扫描仪主要性能指标：==","==①、光学分辨率（dpi）：反映图像大小，分辨率越高，扫描后的图像越大、越清晰，例如 1200×2400 dpi；分辨率决定了扫描仪的档次和价格。==","==②、色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实，例如 32 bit。==","==③、扫描幅面：指被扫描原稿的最大尺寸，例如 A3、A4 等。==","==④、与主机的接口类型：SCSI、USB、IEEE 1394 接口。==","4、数码相机（图像输入设备）","(1) 工作原理：镜头和快门与传统相机基本相同，不同之处是它不使用光敏卤化银胶片成像，而是将影像聚焦在成像芯片（CCD 或 CMOS）上，并由成像芯片转换成电信号，再经模数转换（A/D 转换）变成数字图像，经必要的图像处理和数据压缩之后，存储在相机内部的存储器中。其中成像芯片是数码相机的核心。CCD 上的信号要经过正确的转换部件转换为数字信号，方能存储在存储卡中；信息是模拟信号形式，需要经过 A/D 转换部件转换为数字信号。","^^(2) 成像芯片：CCD（电荷耦合器）或 CMOS（互补金属氧化物半导体）。^^","^^(3) 数码相机默认使用 JPG（JPEG 的简称） 格式；部分专业摄影师使用 RAW 格式，是一种无损压缩图像格式。^^","^^(4) 性能指标：分辨率（dpi）、存储容量。CCD 像素数目越高，影像分辨率与画质越好，200 万像素可满足基本要求；存储容量越大，可存储的照片越多（还取决于单张图像分辨率）。^^","==(5) 数码相机的存储卡大多采用快擦除（闪速）存储器，即使断电也不会丢失信息。==","(6) 接口：USB、IEEE 1394 接口。","5、摄像头（视频输入设备）","^^(1) 摄像头是一种视频输入设备，获取现实世界中景物的连续图像，数字化后输送至计算机处理。^^","(2) 分类：数字摄像头和模拟摄像头","^^(3) 主要组成部件：镜头、CCD/CMOS、电源^^","^^(4) 性能指标：分辨率（dpi）、色域（RGB24、YUV）、图像压缩方式（静态 JPEG）、彩色深度^^","^^(5) 接口：RS232、USB、IEEE 1394 接口。^^","6、传感器（输入设备）","^^(1) 传感器是一种检测装置，能感知被检测的信息并转换为电信号，供计算机处理（测量、转换、存储、显示或传输）。^^","^^(2) 触摸屏、摄像头、微型话筒等设备的核心都是传感器。^^","(3) 现代键盘、鼠标普遍采用 USB-C（Type-C）或 USB 3.1/3.2 接口；无线键鼠多采用 2.4GHz 或蓝牙连接。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-4-1-b2","imp":"core","kind":"tip","text":"常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是==光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）==；鼠标主要性能参数包括==分辨率（DPI）与刷新率==。","title":"考向复习提示：常用输入设备分类及技术指标"},{"t":"callout","id":"a1-1-4-1-b3","imp":"core","kind":"trap","text":"键盘上敲击一个按键向主机发送的是硬件==扫描码（与按键物理位置相关）==，而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。","title":"高频易错陷阱：扫描码与 ASCII 码的区别"}]$kbv11$::jsonb, $kbv11s$A1-1.4.1 键盘，鼠标，笔输入设备，扫描仪，数字摄像头概述。 1、常用输入设备概述 （1）键盘：向计算机输入字母、数字、符号、命令等信息，是计算机必不可少的输入设备。 （2）鼠标：控制屏幕上的鼠标箭头定位，通过按键发出命令；不是必备输入设备，是常用输入设备。 （3）笔输入设备：主要有手写板、手写笔，可替代键盘、鼠标输入字符、命令和作图。 （4）扫描仪：将原稿（图片、照片、底片、书稿）输入计算机的输入设备。 （5）数字摄像头：将现实世界中景物的连续图像数字化后输入计算机的视频输入设备。 （6）外部设备包括输入设备和输出设备；扫描仪、键盘、鼠标、手写板都属于输入设备。 2、笔输入设备（手写板） (1) 作用：兼容键盘、鼠标和写字笔的功能（可替代键盘、鼠标输入字符、命令和作图），输入汉字需要运行“手写汉字识别软件”。 (2) 手写板分类：电阻式、电容式、电磁感应式 (3) 电磁感应笔：发出电磁波，基板接收后计算出笔的位置信息并传给主机，屏幕上实时显示笔迹；笔尖相当于鼠标左键、按钮 1 相当于右键、按钮 2 相当于滚轮。 (4) 与主机接口：串行口、USB。 (5) 触摸屏（智能手机、ATM 机等使用）是在液晶面板上覆盖一层压力板，对压力敏感，手指或笔尖施压时产生电流以确定位置并跟踪，再由软件识别输入信息。 3、扫描仪（图像输入设备） (1) 扫描仪是将原稿（图片、照片、底片、书稿）输入计算机的一种输入设备 (2) 扫描仪输入到计算机中的是原稿的“图像”（bitmap，格式为 TIF），不是图形 (3) 工作原理（平板式）：进行光电转换（CCD，电荷耦合器件），产生电流并输出 (4) 常见扫描仪类型：平板式扫描仪、滚筒式和胶片专用、手持式扫描仪。 ①、平板式扫描仪：主要扫描反射式稿件，适用范围较广，扫描速度、精度、质量较好，适用于家庭与办公；分辨率 300~8000dpi，色彩 24 至 48 位真彩色，成像器件是 CCD（电荷耦合器件）。 ②、滚筒式和胶片专用扫描仪：胶片专用（即底片式或接触式）分辨率高、技术性能强，多用于专业印刷排版，价格较贵，扫描透明胶片分辨率最低 1000dpi，一般 2700dpi 以上；滚筒式光学分辨率 300dpi，有彩色和灰度两种，彩色型号一般为 24 位，极少数采用 CCD 技术。 ③、手持式扫描仪：扫描头较窄，只适用于扫描较小的图件。 (5) 扫描仪主要性能指标： ①、光学分辨率（dpi）：反映图像大小，分辨率越高，扫描后的图像越大、越清晰，例如 1200×2400 dpi；分辨率决定了扫描仪的档次和价格。 ②、色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实，例如 32 bit。 ③、扫描幅面：指被扫描原稿的最大尺寸，例如 A3、A4 等。 ④、与主机的接口类型：SCSI、USB、IEEE 1394 接口。 4、数码相机（图像输入设备） (1) 工作原理：镜头和快门与传统相机基本相同，不同之处是它不使用光敏卤化银胶片成像，而是将影像聚焦在成像芯片（CCD 或 CMOS）上，并由成像芯片转换成电信号，再经模数转换（A/D 转换）变成数字图像，经必要的图像处理和数据压缩之后，存储在相机内部的存储器中。其中成像芯片是数码相机的核心。CCD 上的信号要经过正确的转换部件转换为数字信号，方能存储在存储卡中；信息是模拟信号形式，需要经过 A/D 转换部件转换为数字信号。 (2) 成像芯片：CCD（电荷耦合器）或 CMOS（互补金属氧化物半导体）。 (3) 数码相机默认使用 JPG（JPEG 的简称） 格式；部分专业摄影师使用 RAW 格式，是一种无损压缩图像格式。 (4) 性能指标：分辨率（dpi）、存储容量。CCD 像素数目越高，影像分辨率与画质越好，200 万像素可满足基本要求；存储容量越大，可存储的照片越多（还取决于单张图像分辨率）。 (5) 数码相机的存储卡大多采用快擦除（闪速）存储器，即使断电也不会丢失信息。 (6) 接口：USB、IEEE 1394 接口。 5、摄像头（视频输入设备） (1) 摄像头是一种视频输入设备，获取现实世界中景物的连续图像，数字化后输送至计算机处理。 (2) 分类：数字摄像头和模拟摄像头 (3) 主要组成部件：镜头、CCD/CMOS、电源 (4) 性能指标：分辨率（dpi）、色域（RGB24、YUV）、图像压缩方式（静态 JPEG）、彩色深度 (5) 接口：RS232、USB、IEEE 1394 接口。 6、传感器（输入设备） (1) 传感器是一种检测装置，能感知被检测的信息并转换为电信号，供计算机处理（测量、转换、存储、显示或传输）。 (2) 触摸屏、摄像头、微型话筒等设备的核心都是传感器。 (3) 现代键盘、鼠标普遍采用 USB-C（Type-C）或 USB 3.1/3.2 接口；无线键鼠多采用 2.4GHz 或蓝牙连接。 考向复习提示：常用输入设备分类及技术指标 常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）；鼠标主要性能参数包括分辨率（DPI）与刷新率。 高频易错陷阱：扫描码与 ASCII 码的区别 键盘上敲击一个按键向主机发送的是硬件扫描码（与按键物理位置相关），而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。$kbv11s$),(54, $kbv11$[{"t":"list","id":"a1-1-4-2-v1","imp":"core","items":["==1、键盘（字符与命令输入设备）==","^^(1) 向计算机输入字母、数字、符号、命令等信息^^","^^(2) 布局：功能键（ESC、F1~F12）、打字键盘（字母键、数字键、符号、修饰键（Ctrl、Shift、Alt 等））、光标控制键、小键盘（数字、数学运算符号等）、其他键（Windows 控制键、多媒体播放控制键等）^^","==(3) 键盘是计算机必不可少的输入设备==","==(4) 为了方便盲打，键盘上有两个定位，分别是“F”键和“J”键==","^^(5) 键盘有机械式（早期使用）和电容式（目前主流）。^^","==(6) 常用接口：USB（2.0、3.0）、PS/2（紫色接口）、无线接口（红外或者无线电波，需接收器插入 USB 接口）。==","^^(7) 电容式键盘特点：无磨损和接触不良问题，耐久性、灵敏度和稳定性都比较好，击键声音小，手感较好，寿命较长。^^"],"title":"","ordered":false},{"t":"img","id":"a1-1-4-2-vi1","imp":"normal","src":"/kb-assets/theory/p17_r1_3d48b69c58426c38.png","w":2220,"h":586,"title":"USB 键盘 / PS/2 键盘 / 无线键盘"},{"t":"list","id":"a1-1-4-2-v2","imp":"core","items":["==2、鼠标（命令输入设备）==","^^(1) 作用：控制屏幕上的鼠标箭头准确地定位在指定的位置处，然后通过按键（左键或右键）发出命令，完成各种操作。^^","==(2) 鼠标不是计算机必备输入设备，是常用输入设备。==","^^(3) 鼠标分类：机械式鼠标（过去使用）和光电式鼠标（目前主流）。光电鼠标的特点相对于传统的机械式鼠标，具有定位准确、移动流畅且不易脏污等优点，不需要专用垫板。^^","^^(4) 基本操作：功能随着应用软件的不同而不同（具体按键功能与应用软件有关，见图 1-2）。^^","^^(5) 光电式鼠标通过激光或红外线识别鼠标器移动的方向和距离，使用微型镜头拍摄其下方的图像，由 DSP（数字信号处理）分析判断鼠标器的移动方向和距离。^^","^^(6) 性能指标参数：鼠标的分辨率是指鼠标每移动 1 英寸光标在屏幕上通过的像素数目，使用 dpi（dot per inch）表示；分辨率越高，移动速度越快，定位越准；一般在 800CPI（动态）～1600 之间最合适。^^","^^(7) Windows 下鼠标操作及功能：^^","①、单击左键：选择对象（Ctrl+左单：选择多个不连续的；Shift+左单：选择多个连续的），或执行某个菜单；","②、双击左键：打开文件/文件夹，或运行应用程序；","③、左键拖放：移动对象/复制对象（Ctrl+左键拖）/创建对象快捷方式（Alt+左键拖）等；","④、单击右键：弹出所指对象的快捷菜单；","⑤、向前/向后转动滚轮：显示窗口中前面/后面的内容（滚屏）。","(8) Windows 下常见鼠标状态：见下图。"],"title":"","ordered":false},{"t":"img","id":"a1-1-4-2-vi2","imp":"normal","src":"/kb-assets/theory/p18_r0_b6f8ee1670049bd1.png","w":1137,"h":506,"title":""},{"t":"list","id":"a1-1-4-2-v3","imp":"core","items":["==(9) 常用鼠标接口：RS-232（已不使用）、PS/2（绿色，很少使用）、USB（主流）、无线鼠标（需要接收器）。=="],"title":"","ordered":false},{"t":"img","id":"a1-1-4-2-vi3","imp":"normal","src":"/kb-assets/theory/p18_r1_daf8174c7cdbf997.png","w":1337,"h":340,"title":""},{"t":"list","id":"a1-1-4-2-v4","imp":"core","items":["==(10) 笔记本电脑使用轨迹球、操纵杆和触摸板等代替鼠标（功能）作为系统定点设备。==","(11) 功能键 F1～F12 的作用由前台程序决定：键盘上的 12 个功能键的具体功能，由正在前台执行的程序决定。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-4-2-b8","imp":"core","kind":"tip","text":"鼠标按工作原理分为：机械滚球鼠标（已淘汰）、光电鼠标（红外发光二极管）、激光鼠标（精度更高适配表面广）；现代鼠标主流采用 ==USB 接口、2.4GHz 无线接收器接口或蓝牙接口==，传统台式机的绿色 PS/2 圆口已逐步退出市场。","title":"考向复习提示：鼠标工作原理与常见物理接口"},{"t":"callout","id":"a1-1-4-2-b9","imp":"core","kind":"trap","text":"光电鼠标底部并不是“测量鼠标移动位移”，而是依靠底部的微型 CMOS 传感器==高速连续拍摄工作面的微观图像，由内置 DSP 图像处理器对比前后两张图像的特征点位移差==，从而计算出移动方向与距离；切勿选错为滚轴机械计数或反射强度积分。","title":"高频易错陷阱：光电鼠标定位机理认知误区"}]$kbv11$::jsonb, $kbv11s$A1-1.4.2 键盘，鼠标的分类，工作原理，基本操作，采用的接口类型。 1、键盘（字符与命令输入设备） (1) 向计算机输入字母、数字、符号、命令等信息 (2) 布局：功能键（ESC、F1~F12）、打字键盘（字母键、数字键、符号、修饰键（Ctrl、Shift、Alt 等））、光标控制键、小键盘（数字、数学运算符号等）、其他键（Windows 控制键、多媒体播放控制键等） (3) 键盘是计算机必不可少的输入设备 (4) 为了方便盲打，键盘上有两个定位，分别是“F”键和“J”键 (5) 键盘有机械式（早期使用）和电容式（目前主流）。 (6) 常用接口：USB（2.0、3.0）、PS/2（紫色接口）、无线接口（红外或者无线电波，需接收器插入 USB 接口）。 (7) 电容式键盘特点：无磨损和接触不良问题，耐久性、灵敏度和稳定性都比较好，击键声音小，手感较好，寿命较长。 2、鼠标（命令输入设备） (1) 作用：控制屏幕上的鼠标箭头准确地定位在指定的位置处，然后通过按键（左键或右键）发出命令，完成各种操作。 (2) 鼠标不是计算机必备输入设备，是常用输入设备。 (3) 鼠标分类：机械式鼠标（过去使用）和光电式鼠标（目前主流）。光电鼠标的特点相对于传统的机械式鼠标，具有定位准确、移动流畅且不易脏污等优点，不需要专用垫板。 (4) 基本操作：功能随着应用软件的不同而不同（具体按键功能与应用软件有关，见图 1-2）。 (5) 光电式鼠标通过激光或红外线识别鼠标器移动的方向和距离，使用微型镜头拍摄其下方的图像，由 DSP（数字信号处理）分析判断鼠标器的移动方向和距离。 (6) 性能指标参数：鼠标的分辨率是指鼠标每移动 1 英寸光标在屏幕上通过的像素数目，使用 dpi（dot per inch）表示；分辨率越高，移动速度越快，定位越准；一般在 800CPI（动态）～1600 之间最合适。 (7) Windows 下鼠标操作及功能： ①、单击左键：选择对象（Ctrl+左单：选择多个不连续的；Shift+左单：选择多个连续的），或执行某个菜单； ②、双击左键：打开文件/文件夹，或运行应用程序； ③、左键拖放：移动对象/复制对象（Ctrl+左键拖）/创建对象快捷方式（Alt+左键拖）等； ④、单击右键：弹出所指对象的快捷菜单； ⑤、向前/向后转动滚轮：显示窗口中前面/后面的内容（滚屏）。 (8) Windows 下常见鼠标状态：见下图。 (9) 常用鼠标接口：RS-232（已不使用）、PS/2（绿色，很少使用）、USB（主流）、无线鼠标（需要接收器）。 (10) 笔记本电脑使用轨迹球、操纵杆和触摸板等代替鼠标（功能）作为系统定点设备。 (11) 功能键 F1～F12 的作用由前台程序决定：键盘上的 12 个功能键的具体功能，由正在前台执行的程序决定。 考向复习提示：鼠标工作原理与常见物理接口 鼠标按工作原理分为：机械滚球鼠标（已淘汰）、光电鼠标（红外发光二极管）、激光鼠标（精度更高适配表面广）；现代鼠标主流采用 USB 接口、2.4GHz 无线接收器接口或蓝牙接口，传统台式机的绿色 PS/2 圆口已逐步退出市场。 高频易错陷阱：光电鼠标定位机理认知误区 光电鼠标底部并不是“测量鼠标移动位移”，而是依靠底部的微型 CMOS 传感器高速连续拍摄工作面的微观图像，由内置 DSP 图像处理器对比前后两张图像的特征点位移差，从而计算出移动方向与距离；切勿选错为滚轴机械计数或反射强度积分。$kbv11s$);
do $$
declare r record; o record; v integer;
begin
 for r in select node_id, blocks, search_text from _kbv11 order by node_id loop
  select rev_no, html, source_ref into o from kb_revision where node_id=r.node_id and rev_no=(select published_rev from kb_entry where node_id=r.node_id);
  select coalesce(max(rev_no),0)+1 into v from kb_revision where node_id=r.node_id;
  insert into kb_revision(node_id,rev_no,blocks,html,search_text,source_ref) values (r.node_id,v,r.blocks,o.html,r.search_text,o.source_ref);
  update kb_entry set published_rev=v, updated_at=now() where node_id=r.node_id;
 end loop;
end $$;
commit;
